import argparse,hashlib,json,os,pathlib,re,tempfile
FIELDS=('MemTotal','MemFree','MemAvailable','Buffers','Cached','Slab','SReclaimable','SUnreclaim','Dirty','Writeback','Shmem','SwapTotal','SwapFree')
def parse_meminfo(text):
    if not isinstance(text,str)or len(text)>32768:raise ValueError('bounded meminfo text required')
    result={}
    for line in text.splitlines():
        name,separator,rest=line.partition(':')
        if name not in FIELDS:continue
        match=re.fullmatch(r'\s*([0-9]{1,20})\s+kB\s*',rest)
        if name in result or not separator or match is None:raise ValueError('invalid or duplicate kB counter')
        result[name]=int(match[1])*1000
    if set(result)!=set(FIELDS):raise ValueError('required memory counter missing')
    return result
def parse_free(text):
    if not isinstance(text,str)or len(text)>32768:raise ValueError('bounded free text required')
    rows=[line.split()for line in text.splitlines()if line.strip()]
    headers=('total','used','free','shared','buffers','cache','available')
    if len(rows)!=3 or len(rows[0])!=7 or set(rows[0])!=set(headers)or rows[1][0]!='Mem:'or len(rows[1])!=8 or rows[2][0]!='Swap:'or len(rows[2])!=4:raise ValueError('free bytes wide required')
    if any(re.fullmatch(r'[0-9]{1,20}',v)is None for v in rows[1][1:]+rows[2][1:]):raise ValueError('integer free byte counters required')
    return {'mem':dict(zip(rows[0],map(int,rows[1][1:]))),'swap':dict(zip(('total','used','free'),map(int,rows[2][1:])))}
def inspect_memory(collector):
    if not callable(collector):raise ValueError('collector required')
    evidence=collector();before=parse_meminfo(evidence['meminfo_before']);after=parse_meminfo(evidence['meminfo_after']);free=parse_free(evidence['free_bytes_wide'])
    components={key:after[key]for key in('Buffers','Cached','SReclaimable')};component_sum=sum(components.values())
    summary={'available_estimate_bytes':after['MemAvailable'],'mem_free_bytes':after['MemFree'],'cache_components_bytes':components,'cache_component_sum_not_available_bytes':component_sum,'naive_free_plus_components_not_available_bytes':after['MemFree']+component_sum,'available_minus_free_bytes':after['MemAvailable']-after['MemFree'],'available_delta_bytes':after['MemAvailable']-before['MemAvailable'],'dirty_bytes':after['Dirty'],'writeback_bytes':after['Writeback'],'unreclaimable_slab_bytes':after['SUnreclaim']}
    interpretation={'leak_diagnosis':'not_determined_from_these_observations','available_is_kernel_estimate':True,'cache_fully_available':False,'slab_must_not_be_added_to_its_components':True,'cached_includes_shmem':True,'proc_and_free_are_not_atomic':True,'resident_pages_do_not_prove_reclaimability':True,'cgroup_or_production_diagnosis':False}
    digest=hashlib.sha256(json.dumps(evidence,ensure_ascii=False,sort_keys=True,separators=(',',':'),allow_nan=False).encode()).hexdigest()
    return {'schema':1,'evidence':evidence,'evidence_sha256':digest,'meminfo_bytes':{'before':before,'after':after},'free_bytes':free,'summary':summary,'interpretation':interpretation}
def main():
    parser=argparse.ArgumentParser();parser.add_argument('--output',required=True);args=parser.parse_args();target=pathlib.Path(args.output)
    if target.exists()or target.is_symlink()or not target.parent.is_dir():raise ValueError('new output and existing parent required')
    from native_probe import collect
    report=inspect_memory(collect);raw=(json.dumps(report,ensure_ascii=False,sort_keys=True,allow_nan=False)+'\n').encode();fd,name=tempfile.mkstemp(prefix='.memory019-',dir=target.parent)
    try:
        with os.fdopen(fd,'wb')as stream:stream.write(raw);stream.flush();os.fsync(stream.fileno())
        os.link(name,target)
    finally:os.unlink(name)
    print('{"status":"complete"}')
if __name__=='__main__':
    try:main()
    except Exception as error:
        import sys
        print(type(error).__name__+': '+str(error),file=sys.stderr);raise SystemExit(2)

